<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; class Interaction { public const PING = 1; public const COMMAND = 2; public const COMPONENT = 3; public const AUTOCOMPLETE = 4; public const MODAL = 5; private array $options; private ?string $subcommand = null; public function __construct(public readonly array $payload) { $options = (array) ($payload['data']['options'] ?? []); if (isset($options[0]['type']) && (int) $options[0]['type'] === Commands::SUBCOMMAND) { $this->subcommand = (string) $options[0]['name']; $options = (array) ($options[0]['options'] ?? []); } $this->options = []; foreach ($options as $option) { if (is_array($option) && isset($option['name'])) { $this->options[(string) $option['name']] = $option; } } } public function type(): int { return (int) ($this->payload['type'] ?? 0); } public function token(): string { return (string) ($this->payload['token'] ?? ''); } public function command(): string { return (string) ($this->payload['data']['name'] ?? ''); } public function subcommand(): ?string { return $this->subcommand; } public function option(string $name): mixed { return $this->options[$name]['value'] ?? null; } public function string(string $name): string { return trim((string) ($this->option($name) ?? '')); } public function integer(string $name): ?int { $value = $this->option($name); return is_numeric($value) ? (int) $value : null; } public function focused(): ?array { foreach ($this->options as $name => $option) { if (($option['focused'] ?? false) === true) { return ['name' => $name, 'value' => trim((string) ($option['value'] ?? ''))]; } } return null; } public function customId(): string { return (string) ($this->payload['data']['custom_id'] ?? ''); } public function values(): array { return array_map('strval', (array) ($this->payload['data']['values'] ?? [])); } public function field(string $id): string { foreach ((array) ($this->payload['data']['components'] ?? []) as $row) { $candidates = isset($row['component']) ? [$row['component']] : (array) ($row['components'] ?? []); foreach ($candidates as $component) { if (is_array($component) && ($component['custom_id'] ?? null) === $id) { return trim((string) ($component['value'] ?? '')); } } } return ''; } public function userId(): string { return (string) ($this->payload['member']['user']['id'] ?? $this->payload['user']['id'] ?? ''); } public function user(): array { return (array) ($this->payload['member']['user'] ?? $this->payload['user'] ?? []); } public function username(): string { $user = $this->user(); return (string) ($user['global_name'] ?? $user['username'] ?? 'Discord user'); } public function roles(): array { $roles = array_map('strval', (array) ($this->payload['member']['roles'] ?? [])); $guild = $this->guildId(); if ($guild !== null) { $roles[] = $guild; } return array_values(array_unique($roles)); } public function avatarUrl(): string { $user = $this->user(); $avatar = $user['avatar'] ?? null; if (!is_string($avatar) || $avatar === '') { return 'https://cdn.discordapp.com/embed/avatars/' . ((int) substr($this->userId(), -1) % 5) . '.png'; } return sprintf('https://cdn.discordapp.com/avatars/%s/%s.png?size=128', $this->userId(), $avatar); } public function guildId(): ?string { $guild = $this->payload['guild_id'] ?? null; return is_string($guild) && $guild !== '' ? $guild : null; } public function channelId(): ?string { $channel = $this->payload['channel_id'] ?? $this->payload['channel']['id'] ?? null; return is_string($channel) && $channel !== '' ? $channel : null; } public function botInGuild(): bool { $owners = (array) ($this->payload['authorizing_integration_owners'] ?? []); return $this->guildId() !== null && array_key_exists('0', $owners); } public function canManageGuild(): bool { $permissions = (string) ($this->payload['member']['permissions'] ?? '0'); if (!ctype_digit($permissions)) { return false; } $value = (int) $permissions; return ($value & Commands::ADMINISTRATOR) === Commands::ADMINISTRATOR || ($value & Commands::MANAGE_GUILD) === Commands::MANAGE_GUILD; } public function canMentionEveryone(): bool { $permissions = (string) ($this->payload['member']['permissions'] ?? '0'); if (!ctype_digit($permissions)) { return false; } $value = (int) $permissions; return ($value & Commands::ADMINISTRATOR) === Commands::ADMINISTRATOR || ($value & Commands::MENTION_EVERYONE) === Commands::MENTION_EVERYONE; } public function resolvedChannel(string $id): ?array { $channel = $this->payload['data']['resolved']['channels'][$id] ?? null; return is_array($channel) ? $channel : null; } } 